import sys
import math

def main():
    input = sys.stdin.read
    data = input().strip().split()
    N, M, K = map(int, data)

    def lcm(x, y):
        return (x * y) // math.gcd(x, y)

    lcm_nm = lcm(N, M)

    def count(v):
        return (v // N) + (v // M) - 2 * (v // lcm_nm)

    low, high = 1, 2 * K * max(N, M)

    while low < high:
        mid = (low + high) // 2
        if count(mid) < K:
            low = mid + 1
        else:
            high = mid

    print(low)
